export function lookupKnowledge(term, surface = 'all'){
  const q = String(term || '').toLowerCase();
  return PANEL_LOCATOR_KNOWLEDGE_BASE.filter((item) => (!q || item.term.includes(q) || String(item.label).toLowerCase().includes(q)) && (surface === 'all' || item.surface === surface)).slice(0, 80);
}

export function summarizeKnowledgeBase(){
  const surfaces = new Map();
  for(const item of PANEL_LOCATOR_KNOWLEDGE_BASE){ surfaces.set(item.surface, (surfaces.get(item.surface) || 0) + 1); }
  return { total: PANEL_LOCATOR_KNOWLEDGE_BASE.length, surfaces: Object.fromEntries([...surfaces.entries()].sort()) };
}
